    counts={v:sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}
    bg=max(counts,key=counts.get)
    border=next(v for v in counts if v!=bg and any(row[0]==v or row[-1]==v for row in grid))
    seed=next(v for v in counts if v not in (bg,border))
    sr,sc=next((r,c) for r in range(h) for c in range(w) if grid[r][c]==seed)
    out=[row[:] for row in grid]
    # The edge-color runs define directional fills on each side of the seed.
    for r in range(h):
        if grid[r][0]==border:
            if r<sr:
                for c in range(1,w): out[r][c]=seed
            elif r==sr:
                for c in range(1,sc+1): out[r][c]=seed
            else:
                for c in range(sc): out[r][c]=seed
        if grid[r][-1]==border:
            if r<sr:
                for c in range(sc,w-1): out[r][c]=seed
            elif r==sr:
                for c in range(sc,w-1): out[r][c]=seed
            else:
                for c in range(0,w-1): out[r][c]=seed
    for r in range(h):
        for c in range(w):
            if grid[r][c]==border: out[r][c]=border
    out[sr][sc]=seed
    return out
