    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The input contains edge bars and isolated marker pixels. Each marker
    # projects its color rightward and downward; the marker itself becomes 4.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (6, 9):
                continue
            out[r][c] = 4
            for cc in range(c + 1, w):
                if grid[r][cc] == 9:
                    break
                out[r][cc] = color
            for rr in range(r + 1, h):
                if grid[rr][c] == 9:
                    break
                out[rr][c] = color

    return out
